SELECT  FROM doctors

ORDER BY full_name
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) > 0 FROM doctors
WHERE registration_number = #{registrationNumber}
AND id != #{excludeId}

mapper.update:
UPDATE doctors SET
  department_id = #{departmentId}, full_name = #{fullName}, qualification = #{qualification},
  specialization = #{specialization}, registration_number = #{registrationNumber},
  experience_years = #{experienceYears}, phone = #{phone}, email = #{email}, about = #{about},
  consultation_fee = #{consultationFee}, daily_limit = #{dailyLimit}, updated_by = #{updatedBy}
WHERE id = #{id}
